import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.C0kwIWkz.js";const m=JSON.parse('{"title":"URL parameters","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/docs-changelog-0-6-0/guide/url-parameters.html"}],["meta",{"property":"og:title","content":"URL parameters | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/docs-changelog-0-6-0/guide/url-parameters.html"}],["meta",{"name":"twitter:title","content":"URL parameters | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/url-parameters.md","filePath":"guide/url-parameters.md"}'),r={name:"guide/url-parameters.md"};function c(s,e,i,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="url-parameters" tabindex="-1">URL parameters <a class="header-anchor" href="#url-parameters" aria-label="Permalink to &quot;URL parameters&quot;">​</a></h1><p>The demo viewer reads its state from the URL; <strong>Share</strong> (top right) copies the current view as a link.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td><code>dataset</code></td><td>URL</td><td>OME-Zarr or sharded binary dataset</td></tr><tr><td><code>sourceChannels</code></td><td>zero-based indices, e.g. <code>5,1</code></td><td>1–4 source channels in display order (default: the first four)</td></tr><tr><td><code>timepoint</code></td><td>zero-based index</td><td>Timepoint (default 0)</td></tr><tr><td><code>mode</code></td><td><code>dvr</code>, <code>mip</code>, <code>iso</code>, <code>lod</code>, <code>slice</code></td><td>Render mode</td></tr><tr><td><code>wc</code>, <code>ww</code></td><td>0–1</td><td>Window centre and width</td></tr><tr><td><code>iso</code></td><td>0–1</td><td>Isosurface threshold</td></tr><tr><td><code>density</code></td><td>0.1–10</td><td>DVR opacity scale</td></tr><tr><td><code>shade</code></td><td>0–1</td><td>DVR gradient shading (default 0)</td></tr><tr><td><code>boundary</code></td><td>0–1</td><td>DVR boundary emphasis: opacity follows gradient magnitude (default 0)</td></tr><tr><td><code>tf</code></td><td><code>grayscale</code>, <code>grayscale-inverted</code>, <code>coolwarm</code>, <code>hot</code>, <code>cool</code>, <code>viridis</code>, <code>plasma</code>, <code>seismic</code></td><td>Transfer function preset</td></tr><tr><td><code>tfpts</code></td><td>x,y pairs, e.g. <code>0,0,0.5,0.8,1,1</code></td><td>Transfer function opacity points</td></tr><tr><td><code>up</code></td><td><code>x</code>, <code>y</code>, <code>z</code>, <code>-x</code>, <code>-y</code>, <code>-z</code></td><td>Camera up axis</td></tr><tr><td><code>cam</code></td><td><code>rx,ry,dist,tx,ty,tz</code></td><td>Camera rotation, distance and target</td></tr><tr><td><code>labels</code></td><td>layers, comma-separated: <code>source[:opacity[:3d[:slices[:colour[:segments]]]]]</code></td><td>Label layers in drawing order (see <a href="/preview/docs-changelog-0-6-0/rendering/labels.html">Labels</a>). Source: a name from the dataset&#39;s <code>labels</code> group or a URI-encoded URL, <code>-</code> in front hides the layer. 3D: <code>surface</code>, <code>tint</code>, <code>off</code>; slices: <code>fill</code>, <code>outline</code>, <code>both</code>, <code>off</code>; colour: <code>auto</code> (per segment) or hex RGB; segments: dot-separated <code>i</code> (only selected), <code>s12</code> (select 12), <code>h3</code> (hide 3). E.g. <code>cells,nuclei:0.6:tint</code></td></tr><tr><td><code>proj</code></td><td><code>ortho</code></td><td>Orthographic projection for every view, quad panes included (default perspective; also the grid button under the orientation gizmo, or <code>O</code>)</td></tr><tr><td><code>scale</code></td><td>0.25–1</td><td>Render resolution scale</td></tr><tr><td><code>sse</code></td><td>pixels</td><td>LOD screen-space error threshold (default 8; lower = sharper, more data)</td></tr><tr><td><code>pyramid</code></td><td><code>native</code>, <code>legacy</code></td><td>Level model. Default: native, falling back to legacy if the levels don&#39;t fit; setting it disables the fallback</td></tr><tr><td><code>clipMin</code>, <code>clipMax</code></td><td>x,y,z (0–1)</td><td>Clip box</td></tr><tr><td><code>slices</code></td><td>x,y,z (0–1)</td><td>Slice positions (<code>slice</code> mode)</td></tr><tr><td><code>sliceVis</code></td><td>0–7</td><td>Visible slice planes as a bitmask (X = 1, Y = 2, Z = 4; default 7)</td></tr><tr><td><code>wireframe</code>, <code>axis</code></td><td><code>1</code></td><td>Bounding box and axis overlays</td></tr><tr><td><code>layout</code></td><td><code>quad</code></td><td>Start with front, side and top panes around the 3D view (single-channel viewer; also the grid button in the top bar, or <code>Q</code>). The axis panes pan and zoom but don&#39;t orbit; the controls set the 3D pane&#39;s mode and everything else for all panes</td></tr><tr><td><code>panes</code></td><td>modes, e.g. <code>mip,dvr,slice</code></td><td>Render modes of the front, side and top panes: <code>dvr</code>, <code>mip</code>, <code>iso</code>, <code>slice</code> (default <code>slice</code>)</td></tr></tbody></table><p>Changing <strong>Up Axis</strong> reorients and recenters the axis panes and updates their labels, including when you next open a hidden quad layout. Their render modes are kept; saved camera poses are restored only while the up axis is unchanged.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>?dataset=https://example.com/scan.ome.zarr&amp;mode=mip&amp;wc=0.2&amp;ww=0.3&amp;tf=coolwarm</span></span></code></pre></div><p>The multichannel viewer uses <code>channels</code> and <code>slice</code> instead of the single-channel display parameters: see <a href="/preview/docs-changelog-0-6-0/rendering/multichannel.html#multichannel-demo">Multichannel demo</a>.</p><h2 id="diagnostics-and-experiments" tabindex="-1">Diagnostics and experiments <a class="header-anchor" href="#diagnostics-and-experiments" aria-label="Permalink to &quot;Diagnostics and experiments&quot;">​</a></h2><p>Not included in share links.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>debug=1</code></td><td>Opens the stats panel (also <code>D</code>). Its <strong>Memory</strong> section shows GPU memory (atlas, render targets, labels), the brick and chunk caches with their hit rates, the JS heap where the browser exposes it, and pressure counters (refused allocations, evictions)</td></tr><tr><td><code>bench=1</code></td><td>Once streaming and accumulation have converged, logs a report (timings, bytes, bricks, GPU and cache memory with peaks) and sets <code>window.__KILN_BENCH_RESULT</code>. Options: <code>benchLabel</code>, <code>benchTimeout</code> (ms, default 120000), <code>benchStable</code> (polls, default 8), <code>report=&lt;url&gt;</code> to POST the JSON</td></tr><tr><td><code>benchSweep=1</code></td><td>With <code>bench=1</code>: after the first convergence, orbits the camera once (<code>benchSweepMs</code>, default 6000) so eviction and the caches get exercised, then waits for convergence again and reports the bricks and bytes that took</td></tr><tr><td><code>rayguide=0</code></td><td>Turns off <a href="/preview/docs-changelog-0-6-0/architecture/streaming.html#ray-guided-selection">ray-guided brick selection</a>, which is on by default</td></tr><tr><td><code>softreset=1</code></td><td>Experimental fix for woodgrain while refining: brick commits keep part of the accumulated image and jitter is seeded per pixel (<a href="/preview/docs-changelog-0-6-0/rendering/resolution-taa.html#jitter-and-accumulation">details</a>)</td></tr><tr><td><code>local=true</code></td><td>Set by the viewer after opening a local directory; reopens it on reload</td></tr></tbody></table>',9)])])}const u=t(r,[["render",c]]);export{m as __pageData,u as default};
